import {
  type ReactNode,
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useIntl } from 'react-intl';

import type { GridReadyEvent } from 'ag-grid-community';
import { Legend, NoDataYet, NoResultsState, Skeleton, Table } from 'components';
import { TableDataType } from 'components/Table/types';
import { StyledTitle } from 'shared/Styles';
import { WithEmpty } from 'utils/dataEmpty';

import { tableConfig } from './config';
import { INVESTMENT_BREAKDOWN_LEGEND_CONFIG } from './constants';
import {
  InvestmentBreakdownTableStyles,
  StyledInvestmentBreakdownTableBody,
  StyledInvestmentBreakdownTableChrome,
  StyledInvestmentBreakdownTableLegend,
  StyledInvestmentBreakdownTableTitle,
  StyledInvestmentBreakdownTableTitleActions,
} from './InvestmentBreakdownTable.styles';
import { adjustSubHeaderColSpansForVisibleColumns } from './utils/adjustSubHeaderColSpansForVisibleColumns';
import { applyGroupHeaderMinWidths } from './utils/applyGroupHeaderMinWidths';
import { filterTableDataByHiddenFields } from './utils/filterTableHeaderByHiddenFields';
import { getHiddenColumnIds } from './utils/visibleColumns';

/** Bucket width to reduce layout churn from sub-pixel ResizeObserver updates. */
export const bucketTableContainerWidth = (width: number): number =>
  width <= 0 ? 0 : Math.round(width / 16) * 16;

interface InvestmentBreakdownTableProps {
  data?: WithEmpty<TableDataType>;
  dataTestId?: string;
  visibleColumns?: string[];
  allColumnIds?: string[];
  legend?: boolean;
  title?: string;
  tableCustomization?: ReactNode;
  loading?: boolean;
  isGlobalZone?: boolean;
  onOpenCountryModal?: () => void;
  noResultsDataTestId?: string;
  noDataTestId?: string;
}

export const InvestmentBreakdownTable: React.FC<
  InvestmentBreakdownTableProps
> = ({
  data,
  dataTestId,
  visibleColumns,
  allColumnIds,
  legend = true,
  title,
  tableCustomization,
  loading = false,
  isGlobalZone = false,
  onOpenCountryModal,
  noResultsDataTestId,
  noDataTestId,
}) => {
  const { formatMessage } = useIntl();
  const chromeRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const gridApiRef = useRef<GridReadyEvent['api'] | null>(null);
  const [tableContainerWidth, setTableContainerWidth] = useState(0);

  const updateTableContainerWidth = useCallback((nextWidth: number) => {
    const bucketedWidth = bucketTableContainerWidth(nextWidth);

    if (bucketedWidth <= 0) {
      return;
    }

    setTableContainerWidth((currentWidth) =>
      currentWidth === bucketedWidth ? currentWidth : bucketedWidth,
    );
  }, []);

  const handleGridSizeChanged = useCallback(() => {
    const gridRoot = measureRef.current?.querySelector(
      '.ag-root-wrapper',
    ) as HTMLElement | null;

    if (gridRoot?.clientWidth) {
      updateTableContainerWidth(gridRoot.clientWidth);
    }
  }, [updateTableContainerWidth]);

  const hiddenFields = useMemo(() => {
    if (!visibleColumns || !allColumnIds?.length) {
      return [];
    }

    return getHiddenColumnIds(allColumnIds, visibleColumns);
  }, [allColumnIds, visibleColumns]);

  const hiddenColumnKey = useMemo(
    () =>
      [...hiddenFields]
        .sort((a, b) => String(a).localeCompare(String(b)))
        .join('|') || 'all-columns',
    [hiddenFields],
  );

  useLayoutEffect(() => {
    const elements = [measureRef.current, chromeRef.current].filter(
      (element): element is HTMLDivElement => element != null,
    );

    if (!elements.length) {
      return undefined;
    }

    const measureWidth = () => {
      const widths = elements.map((element) => element.clientWidth);
      const nextWidth = Math.max(...widths);

      updateTableContainerWidth(nextWidth);
    };

    measureWidth();

    const observer = new ResizeObserver(measureWidth);
    elements.forEach((element) => observer.observe(element));

    return () => {
      observer.disconnect();
    };
  }, [loading, hiddenColumnKey, updateTableContainerWidth]);

  useLayoutEffect(
    () => () => {
      gridApiRef.current?.removeEventListener(
        'gridSizeChanged',
        handleGridSizeChanged,
      );
      gridApiRef.current = null;
    },
    [handleGridSizeChanged],
  );

  const handleGridReady = useCallback(
    (event: GridReadyEvent) => {
      const gridRoot = measureRef.current?.querySelector(
        '.ag-root-wrapper',
      ) as HTMLElement | null;

      if (gridRoot?.clientWidth) {
        updateTableContainerWidth(gridRoot.clientWidth);
      }

      if (gridApiRef.current) {
        gridApiRef.current.removeEventListener(
          'gridSizeChanged',
          handleGridSizeChanged,
        );
      }

      gridApiRef.current = event.api;
      event.api.addEventListener('gridSizeChanged', handleGridSizeChanged);
    },
    [handleGridSizeChanged, updateTableContainerWidth],
  );

  const tableLayoutKey = hiddenColumnKey;

  const visibleTableData = useMemo(() => {
    if (!data || data.empty) {
      return undefined;
    }

    const filtered = filterTableDataByHiddenFields(data, hiddenFields);
    const adjustedSpans = adjustSubHeaderColSpansForVisibleColumns(filtered);

    return applyGroupHeaderMinWidths(
      adjustedSpans,
      tableConfig,
      tableContainerWidth,
    );
  }, [data, hiddenFields, tableContainerWidth]);

  const tableTitle =
    title ??
    formatMessage({
      id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.title',
    });

  const renderTableBody = () => {
    if (isGlobalZone) {
      return null;
    }

    if (loading) {
      return (
        <Skeleton
          height="590px"
          width="100%"
          length={1}
          dataTestId={dataTestId ? `skeleton-${dataTestId}` : undefined}
        />
      );
    }

    if (!visibleTableData) {
      return (
        <div
          style={{ display: 'flex', justifyContent: 'center' }}
          data-testid={noDataTestId}
        >
          <NoDataYet />
        </div>
      );
    }

    return (
      <Table
        key={tableLayoutKey}
        data={visibleTableData}
        style={InvestmentBreakdownTableStyles}
        autoHeight
        rowHeight={34}
        headerHeight={34}
        groupHeaderHeight={44}
        columnDefsConfig={tableConfig}
        separatorBetweenGroups={false}
        scrollbarWidth={8}
        manageColumnWidths
        onGridReadyCallback={handleGridReady}
        dataTestId={dataTestId}
      />
    );
  };

  return (
    <>
      <StyledInvestmentBreakdownTableChrome
        ref={chromeRef}
        data-testid={dataTestId ? `chrome-${dataTestId}` : undefined}
        style={isGlobalZone ? { display: 'none' } : undefined}
        aria-hidden={isGlobalZone}
      >
        <StyledInvestmentBreakdownTableTitle>
          <StyledTitle
            size="H3"
            data-testid={dataTestId ? `${dataTestId}-title` : undefined}
          >
            {tableTitle}
          </StyledTitle>
          {tableCustomization ? (
            <StyledInvestmentBreakdownTableTitleActions>
              {tableCustomization}
            </StyledInvestmentBreakdownTableTitleActions>
          ) : null}
        </StyledInvestmentBreakdownTableTitle>

        {legend && (
          <StyledInvestmentBreakdownTableLegend>
            <Legend
              legendPosition="left"
              caption={INVESTMENT_BREAKDOWN_LEGEND_CONFIG.map((item) => ({
                ...item,
                pointStyle: 'roundedThicker',
              }))}
              dataTestId={dataTestId ? `${dataTestId}-legend` : undefined}
            />
          </StyledInvestmentBreakdownTableLegend>
        )}

        <StyledInvestmentBreakdownTableBody>
          <div ref={measureRef} style={{ width: '100%' }}>
            {renderTableBody()}
          </div>
        </StyledInvestmentBreakdownTableBody>
      </StyledInvestmentBreakdownTableChrome>

      {isGlobalZone ? (
        <NoResultsState
          type="investmentBreakdown"
          openModal={onOpenCountryModal}
          headerTitleId="ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.noCountrySelectedTitle"
          descriptionId="ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.noCountrySelectedDescription"
          buttonTextId="ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.selectACountry"
          dataTestId={noResultsDataTestId}
        />
      ) : null}
    </>
  );
};
